def encode_session(*, system: str | None, history: tuple[ChatMessage, ...]) -> str:
    """Return a JSON session artifact containing only public semantics."""
    payload = {
        "version": _SESSION_VERSION,
        "system": system,
        "history": [_encode_message(message) for message in history[:-1]] if len(history) > 1 else [_encode_message(message) for message in history],
